package com.sami.app.purchasing.service;
import com.sami.app.common.tenancy.TenantContext; import com.sami.app.common.exception.*; import com.sami.app.organization.service.OrganizationScopeService; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Service @RequiredArgsConstructor public class PurchaseOrderService {private final JdbcTemplate jdbc;private final TenantContext tenants;private final OrganizationScopeService scope;
 @Transactional public Map<String,Object> create(Long company,Long branch,Long supplier,List<Map<String,Object>> lines,String notes){Long t=tenants.requireTenantId();scope.requireScope(company,branch);if(lines==null||lines.isEmpty())throw new ApiException(ErrorCode.VALIDATION_FAILED,"Purchase order requires items");String n="PO-"+jdbc.queryForObject("select nextval('purchase_order_number_seq')",Long.class);BigDecimal total=BigDecimal.ZERO;jdbc.update("insert into purchase_orders(tenant_id,company_id,branch_id,supplier_id,order_number,order_date,notes) values(?,?,?,?,?,?,?)",t,company,branch,supplier,n,LocalDate.now(),notes);Long id=jdbc.queryForObject("select id from purchase_orders where tenant_id=? and order_number=?",Long.class,t,n);for(Map<String,Object> l:lines){BigDecimal q=new BigDecimal(l.get("quantity").toString()),p=new BigDecimal(l.get("unitPrice").toString()),v=q.multiply(p);total=total.add(v);jdbc.update("insert into purchase_order_lines(tenant_id,purchase_order_id,product_id,quantity,unit_price,line_total) values(?,?,?,?,?,?)",t,id,l.get("productId"),q,p,v);}jdbc.update("update purchase_orders set subtotal=?,total=? where id=? and tenant_id=?",total,total,id,t);return jdbc.queryForMap("select * from purchase_orders where tenant_id=? and id=?",t,id);}
 @Transactional public void submit(Long id){updateStatus(id,"DRAFT","SUBMITTED");} @Transactional public void approve(Long id){updateStatus(id,"SUBMITTED","APPROVED");} @Transactional public void cancel(Long id){updateStatus(id,"DRAFT","CANCELLED");} private void updateStatus(Long id,String from,String to){Long t=tenants.requireTenantId();int n=jdbc.update("update purchase_orders set status=?,updated_at=now(),version=version+1 where tenant_id=? and id=? and status=?",to,t,id,from);if(n==0)throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,"Invalid Purchase Order status transition");}
}
